/**
 * Heartfall – pure, deterministic rules.
 *
 * A round is fully described by its Config (generated by the host) plus the
 * ordered list of selected pieces. Both phones replay the same list and
 * therefore always agree on cracks, turn, result and scores.
 */

export type Player = "host" | "guest";

export const PIECE_COUNT = 12;
export const FRAGILE_COUNT = 3;
/** The heart shatters on this crack. */
export const MAX_CRACKS = 3;

export interface Config {
  /** Host-generated id of the session (changes when the host re-opens the game). */
  gameId: number;
  round: number;
  /** Indices of the fragile pieces. Hidden in the UI (not cryptographically secret). */
  fragile: readonly number[];
  firstPlayer: Player;
}

export type Result = { kind: "break"; loser: Player; winner: Player } | { kind: "draw" };

export interface Board {
  /** Piece is gone (safe piece removed) or used (fragile piece cracked). */
  used: readonly boolean[];
  /** Fragile pieces that have been selected, in order. */
  crackedPieces: readonly number[];
  cracks: number;
  remaining: number;
  /** Who moves next (meaningless once `over`). */
  turn: Player;
  over: boolean;
  result: Result | null;
  lastPiece: number | null;
  lastWasFragile: boolean;
}

export const other = (p: Player): Player => (p === "host" ? "guest" : "host");

/** Round 1: host starts. The starting player alternates every round. */
export const starterForRound = (round: number): Player => (round % 2 === 1 ? "host" : "guest");

/** Players simply alternate every move, starting with the round's first player. */
export const moverOf = (cfg: Config, moveIndex: number): Player =>
  moveIndex % 2 === 0 ? cfg.firstPlayer : other(cfg.firstPlayer);

export const isPieceIndex = (v: unknown): v is number =>
  typeof v === "number" && Number.isInteger(v) && v >= 0 && v < PIECE_COUNT;

export function isValidFragile(f: unknown): f is number[] {
  return Array.isArray(f) && f.length === FRAGILE_COUNT && f.every(isPieceIndex) && new Set(f).size === f.length;
}

/** Picks FRAGILE_COUNT distinct pieces. Only the host calls this. */
export function generateFragile(rand: () => number = Math.random): number[] {
  const pool = Array.from({ length: PIECE_COUNT }, (_, i) => i);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, FRAGILE_COUNT).sort((a, b) => a - b);
}

export function emptyBoard(cfg: Config): Board {
  return {
    used: new Array<boolean>(PIECE_COUNT).fill(false),
    crackedPieces: [],
    cracks: 0,
    remaining: PIECE_COUNT,
    turn: cfg.firstPlayer,
    over: false,
    result: null,
    lastPiece: null,
    lastWasFragile: false,
  };
}

/** Applies one selection by whoever's turn it is. `null` if the move is invalid. */
export function applyMove(cfg: Config, board: Board, piece: number): Board | null {
  if (board.over || !isPieceIndex(piece) || board.used[piece]) return null;
  const mover = board.turn;
  const used = board.used.slice();
  used[piece] = true;
  const fragile = cfg.fragile.includes(piece);
  const crackedPieces = fragile ? [...board.crackedPieces, piece] : board.crackedPieces;
  const cracks = crackedPieces.length;
  const remaining = board.remaining - 1;

  let result: Result | null = null;
  if (cracks >= MAX_CRACKS) result = { kind: "break", loser: mover, winner: other(mover) };
  else if (remaining === 0) result = { kind: "draw" };

  return {
    used,
    crackedPieces,
    cracks,
    remaining,
    turn: other(mover),
    over: result !== null,
    result,
    lastPiece: piece,
    lastWasFragile: fragile,
  };
}

/** Rebuilds the board from the move list; `null` if any move is invalid. */
export function replay(cfg: Config, moves: readonly number[]): Board | null {
  let b: Board | null = emptyBoard(cfg);
  for (const m of moves) {
    b = applyMove(cfg, b, m);
    if (!b) return null;
  }
  return b;
}

export interface Scores {
  host: number;
  guest: number;
}

/** Winner +1, loser 0, draw 0 each. */
export function addResult(scores: Scores, result: Result | null): Scores {
  if (!result || result.kind === "draw") return scores;
  return { ...scores, [result.winner]: scores[result.winner] + 1 };
}
